// ── LocalStorage "Database" ────────────────────────────────────────────────
import { useState, useEffect } from 'react'

const KEYS = {
  selections:     'mmu_selections',
  specialtyTrees: 'mmu_specialty_trees',
  users:          'mmu_users',
  admins:         'mmu_admins',
  submissions:    'mmu_submissions',
  results:        'mmu_results',
  settings:       'mmu_system_settings',
  userArchives:   'mmu_user_archives',
  treeArchives:   'mmu_tree_archives',
  logs:           'mmu_logs',
}

// ── Bütün köhnə məlumatları bir dəfəlik sil ──────────────────────────────────
;(() => {
  if (localStorage.getItem('mmu_clean_v3')) return
  const allKeys = Object.keys(localStorage)
  allKeys.forEach(k => {
    if (k.startsWith('mmu_') || k === 'dist_snapshots') {
      localStorage.removeItem(k)
    }
  })
  localStorage.setItem('mmu_clean_v3', '1')
})()

// ── Raw helpers ──────────────────────────────────────────────────────────────
const raw = {
  get: (key: string): any[] => JSON.parse(localStorage.getItem(key) || 'null') || [],
  set: (key: string, val: any) => localStorage.setItem(key, JSON.stringify(val)),
}

// ── ID generator ─────────────────────────────────────────────────────────────
const uid = (prefix = 'id') => `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`

// ── Tree node helpers (recursive) ────────────────────────────────────────────
function walkNodes(nodes: any[], fn: (n: any) => void) {
  for (const n of nodes) { fn(n); if (n.children?.length) walkNodes(n.children, fn) }
}

function getLeaves(nodes: any[]): any[] {
  const leaves: any[] = []
  walkNodes(nodes, n => { if (!n.children?.length) leaves.push(n) })
  return leaves
}

export function buildNameMap(tree: any): Record<string, string> {
  const map: Record<string, string> = {}
  if (!tree) return map
  walkNodes(tree.nodes || [], n => { map[n.id] = n.name })
  return map
}

function shuffle(arr: string[], seed: number): string[] {
  return [...arr].sort((a, b) => {
    const ha = (seed * (a.charCodeAt(0) + (a.charCodeAt(1) || 0) * 3 + (a.charCodeAt(2) || 0) * 7)) % 97
    const hb = (seed * (b.charCodeAt(0) + (b.charCodeAt(1) || 0) * 3 + (b.charCodeAt(2) || 0) * 7)) % 97
    return ha - hb
  })
}

// ── Selections ────────────────────────────────────────────────────────────────
export const selectionDb = {
  getAll: ()         => raw.get(KEYS.selections),
  get:    (id: string) => raw.get(KEYS.selections).find((s: any) => s.id === id) || null,
  create: (data: any) => {
    const item = { ...data, id: uid('sel'), createdAt: new Date().toISOString(), status: 'draft' }
    raw.set(KEYS.selections, [...raw.get(KEYS.selections), item])
    return item
  },
  update: (id: string, data: any) => {
    const list = raw.get(KEYS.selections).map((s: any) => s.id === id ? { ...s, ...data } : s)
    raw.set(KEYS.selections, list)
    return list.find((s: any) => s.id === id)
  },
  delete: (id: string) => {
    raw.set(KEYS.selections, raw.get(KEYS.selections).filter((s: any) => s.id !== id))
  },
  publish: (id: string) => selectionDb.update(id, { status: 'published', publishedAt: new Date().toISOString() }),
  close:   (id: string) => selectionDb.update(id, { status: 'closed',    closedAt:   new Date().toISOString() }),
  archive: (id: string) => selectionDb.update(id, { status: 'archived',  archivedAt: new Date().toISOString() }),
  restore: (id: string) => selectionDb.update(id, { status: 'closed' }),
  getArchived: ()       => raw.get(KEYS.selections).filter((s: any) => s.status === 'archived'),
}

// ── Specialty Trees ───────────────────────────────────────────────────────────
export const treeDb = {
  getAll: ()           => raw.get(KEYS.specialtyTrees),
  get:    (id: string) => raw.get(KEYS.specialtyTrees).find((t: any) => t.id === id) || null,
  create: (data: any)  => {
    const item = { ...data, id: uid('tree'), createdAt: new Date().toISOString(), nodes: [] }
    raw.set(KEYS.specialtyTrees, [...raw.get(KEYS.specialtyTrees), item])

    return item
  },
  update: (id: string, data: any) => {
    const list = raw.get(KEYS.specialtyTrees).map((t: any) => t.id === id ? { ...t, ...data } : t)
    raw.set(KEYS.specialtyTrees, list)
    return list.find((t: any) => t.id === id)
  },
  delete: (id: string) => {
    raw.set(KEYS.specialtyTrees, raw.get(KEYS.specialtyTrees).filter((t: any) => t.id !== id))
  },
  countSpecialties: (tree: any) => getLeaves(tree.nodes || []).length,
  totalQuota:       (tree: any) => getLeaves(tree.nodes || []).reduce((s: number, n: any) => s + (n.quota || 0), 0),
}

// ── Users ─────────────────────────────────────────────────────────────────────
export const userDb = {
  getAll: ()     => raw.get(KEYS.users),
  get:    (id: string)   => raw.get(KEYS.users).find((u: any) => u.id === id) || null,
  create: (data: any) => {
    const item = { ...data, id: uid('std') }
    raw.set(KEYS.users, [...raw.get(KEYS.users), item])
    return item
  },
  update: (id: string, data: any) => {
    const list = raw.get(KEYS.users).map((u: any) => u.id === id ? { ...u, ...data } : u)
    raw.set(KEYS.users, list)
  },
  deleteMany: (ids: string[]) => {
    const set = new Set(ids)
    raw.set(KEYS.users, raw.get(KEYS.users).filter((u: any) => !set.has(u.id)))
  },
}


