// -- TEST: 50 kursant ucun submission (secim siralamasi, bir defelik) --
;(() => {
  if (localStorage.getItem('mmu_test50_subs_v1')) return
  const leaves = ['T_A1a', 'T_A1b', 'T_A2a', 'T_B1a', 'T_B1b']
  let subList = JSON.parse(localStorage.getItem('mmu_submissions') || '[]').filter((s) => s.selectionId !== 'sel_test50')
  const now = new Date().toISOString()
  for (let i = 1; i <= 50; i++) {
    const k = (i - 1) % 5
    const ranking = [...leaves.slice(k), ...leaves.slice(0, k)]
    subList.push({ id: 'sub_test50_' + i, userId: 'std_test50_' + i, selectionId: 'sel_test50', ranking, createdAt: now })
  }
  localStorage.setItem('mmu_submissions', JSON.stringify(subList))
  const users = JSON.parse(localStorage.getItem('mmu_users') || '[]').map((u) =>
    u.institution === 'test50' ? { ...u, status: 'submitted' } : u)
  localStorage.setItem('mmu_users', JSON.stringify(users))
  localStorage.setItem('mmu_test50_subs_v1', '1')
})()

