export const adminDb = {
  getAll: ()     => raw.get(KEYS.admins),
  create: (data: any) => {
    const item = { ...data, id: uid('adm'), status: 'active', lastLogin: '—' }
    raw.set(KEYS.admins, [...raw.get(KEYS.admins), item])
    return item
  },
  update: (id: string, data: any) => {
    const list = raw.get(KEYS.admins).map((a: any) => a.id === id ? { ...a, ...data } : a)
    raw.set(KEYS.admins, list)
  },
  delete: (id: string) => {
    raw.set(KEYS.admins, raw.get(KEYS.admins).filter((a: any) => a.id !== id))
  },
  loginAdmin: (username: string, password: string) => {
    const list = raw.get(KEYS.admins)
    return list.find((a: any) =>
      (a.role === 'superadmin' || a.role === 'admin' || a.role === 'moderator' || a.role === 'operator') &&
      a.username === username.trim() &&
      a.password === password &&
      a.status === 'active'
    ) || null
  },
  loginOperator: (username: string, password: string) => {
    const list = raw.get(KEYS.admins)
    return list.find((a: any) =>
      a.role === 'operator' &&
      a.username === username.trim() &&
      a.password === password &&
      a.status === 'active'
    ) || null
  },
}

// ── Submissions ───────────────────────────────────────────────────────────────
export const submissionDb = {
  getAll: () => raw.get(KEYS.submissions),
  getByUser: (userId: string, selId: string) =>
    raw.get(KEYS.submissions).find((s: any) => s.userId === userId && s.selectionId === selId) || null,
  getBySelection: (selId: string) =>
    raw.get(KEYS.submissions).filter((s: any) => s.selectionId === selId),
  save: (data: any) => {
    const list = raw.get(KEYS.submissions)
    const idx  = list.findIndex((s: any) => s.userId === data.userId && s.selectionId === data.selectionId)
    if (idx >= 0) {
      list[idx] = { ...list[idx], ...data, updatedAt: new Date().toISOString() }
    } else {
      list.push({ ...data, id: uid('sub'), createdAt: new Date().toISOString() })
    }
    raw.set(KEYS.submissions, list)
  },
}

// ── Institutions ──────────────────────────────────────────────────────────────
export const institutionDb = {
  getAll: (): any[] => {
    const stored = localStorage.getItem('mmu_institutions')
    if (!stored) {
      localStorage.setItem('mmu_institutions', JSON.stringify([]))
      return []
    }
    return JSON.parse(stored)
  },
  create: (label: string, icon: string) => {
    const list = institutionDb.getAll()
    const slug = label.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '')
    const id   = (slug || 'inst') + '_' + Date.now().toString(36)
    const item = { id, label, icon }
    list.push(item)
    localStorage.setItem('mmu_institutions', JSON.stringify(list))
    return item
  },
  update: (id: string, data: { label: string; icon: string }) => {
    const list = institutionDb.getAll().map((i: any) => i.id === id ? { ...i, ...data } : i)
    localStorage.setItem('mmu_institutions', JSON.stringify(list))
  },
  delete: (id: string) => {
    const list = institutionDb.getAll().filter((i: any) => i.id !== id)
    localStorage.setItem('mmu_institutions', JSON.stringify(list))
  },
}

