// ── React hook ────────────────────────────────────────────────────────────────
export function useLocalState(fetcher: () => any): [any, () => void] {
  const [data, setData] = useState(fetcher)
  const refresh = () => setData(fetcher())
  useEffect(() => { refresh() }, [])
  return [data, refresh]
}

// ── Logs ──────────────────────────────────────────────────────────────────────
export type LogCategory = 'system' | 'selection' | 'distribution' | 'user' | 'admin'
export type LogType     = 'info' | 'success' | 'warning' | 'error'

export interface LogEntry {
  id:        string
  category:  LogCategory
  type:      LogType
  message:   string
  detail?:   string
  actor?:    string
  timestamp: string
}

export const logDb = {
  getAll: (): LogEntry[] => {
    const stored = localStorage.getItem(KEYS.logs)
    if (!stored) {
      localStorage.setItem(KEYS.logs, JSON.stringify([]))
      return []
    }
    return JSON.parse(stored)
  },
  add: (entry: Omit<LogEntry, 'id' | 'timestamp'>): LogEntry => {
    const list = logDb.getAll()
    const item: LogEntry = {
      ...entry,
      id:        uid('log'),
      timestamp: new Date().toISOString(),
    }
    list.unshift(item)
    const trimmed = list.slice(0, 1000)
    localStorage.setItem(KEYS.logs, JSON.stringify(trimmed))
    return item
  },
  clear: () => {
    localStorage.setItem(KEYS.logs, JSON.stringify([]))
  },
}

export function addLog(
  category: LogCategory,
  type:     LogType,
  message:  string,
  detail?:  string,
  actor?:   string
) {
  // Actor verilməyibsə cari sessiyadakı şəxsin adını götür
  let who = actor
  if (!who) {
    try {
      const a = JSON.parse(sessionStorage.getItem('admin_session')    || 'null')
      const o = JSON.parse(sessionStorage.getItem('operator_session') || 'null')
      const s = JSON.parse(sessionStorage.getItem('mmu_student')      || 'null')
      who = a?.name || o?.name || s?.name || 'Sistem'
    } catch { who = 'Sistem' }
  }
  logDb.add({ category, type, message, detail, actor: who })
}

// ── Seçimi sıfırla + avtomatik seçim ─────────────────────────────────────────
export function resetAndAutoSeedSubmissions(selectionId: string): { count: number } {
  const selList: any[] = JSON.parse(localStorage.getItem(KEYS.selections)     || '[]')
  const treeList: any[]= JSON.parse(localStorage.getItem(KEYS.specialtyTrees) || '[]')
  const userList: any[]= JSON.parse(localStorage.getItem(KEYS.users)          || '[]')
  let   subList: any[] = JSON.parse(localStorage.getItem(KEYS.submissions)    || '[]')

  const sel  = selList.find((s: any) => s.id === selectionId)
  if (!sel) return { count: 0 }

  const tree = treeList.find((t: any) => t.id === sel.treeId)

  function collectLeaves(nodes: any[]): string[] {
    const ids: string[] = []
    for (const n of nodes) {
      if (!n.children?.length) ids.push(n.id)
      else ids.push(...collectLeaves(n.children))
    }
    return ids
  }
  const leafIds = tree ? collectLeaves(tree.nodes || []) : []

  subList = subList.filter((s: any) => s.selectionId !== selectionId)
  const instUsers = userList.filter((u: any) => u.institution === sel.institution)
  const now = new Date().toISOString()
  const newSubs = instUsers.map((u: any, idx: number) => ({
    id:          `sub_reset_${selectionId}_${idx + 1}`,
    userId:      u.id,
    selectionId,
    ranking:     shuffle(leafIds, (idx + 1) * 61 + 17),
    createdAt:   now,
  }))
  subList.push(...newSubs)
  localStorage.setItem(KEYS.submissions, JSON.stringify(subList))
  return { count: newSubs.length }
}

// ── Sistem Parametrləri ───────────────────────────────────────────────────────
export interface LoginFieldConfig {
  column:   string   // 'fin' | 'workNumber' | 'name' | 'parentName' | ...
  label:    string   // ekranda göstərilən ad
  min:      number
  max:      number
  required: boolean
}

export interface InstLoginConfig {
  field1: LoginFieldConfig
  field2: LoginFieldConfig
}

export interface SystemSettings {
  instLogin: Record<string, InstLoginConfig>  // instId → config
  redirectDelaySec?: number                    // seçimdən sonra login-ə qayıtma vaxtı (saniyə)
}

export const DEFAULT_FIELD1: LoginFieldConfig = { column: 'fin',        label: 'FİN Kodu',    min: 1, max: 20, required: true }
export const DEFAULT_FIELD2: LoginFieldConfig = { column: 'workNumber', label: 'İş Nömrəsi',  min: 1, max: 20, required: true }

export const DEFAULT_INST_CONFIG: InstLoginConfig = { field1: DEFAULT_FIELD1, field2: DEFAULT_FIELD2 }

const DEFAULT_SETTINGS: SystemSettings = { instLogin: {}, redirectDelaySec: 10 }

export const systemSettingsDb = {
  get: (): SystemSettings => {
    try {
      const s = localStorage.getItem(KEYS.settings)
      return s ? { ...DEFAULT_SETTINGS, ...JSON.parse(s) } : { ...DEFAULT_SETTINGS }
    } catch { return { ...DEFAULT_SETTINGS } }
  },
  getInstConfig: (instId: string): InstLoginConfig => {
    const s = systemSettingsDb.get()
    const cfg = s.instLogin?.[instId]
    if (!cfg) return { field1: { ...DEFAULT_FIELD1 }, field2: { ...DEFAULT_FIELD2 } }
    return {
      field1: { ...DEFAULT_FIELD1, ...cfg.field1 },
      field2: { ...DEFAULT_FIELD2, ...cfg.field2 },
    }
  },
  setInstConfig: (instId: string, cfg: InstLoginConfig) => {
    const s = systemSettingsDb.get()
    s.instLogin = { ...(s.instLogin || {}), [instId]: cfg }
    localStorage.setItem(KEYS.settings, JSON.stringify(s))
  },
  getRedirectDelay: (): number => {
    const v = systemSettingsDb.get().redirectDelaySec
    return (typeof v === 'number' && v >= 0) ? v : 10
  },
  setRedirectDelay: (sec: number) => {
    const s = systemSettingsDb.get()
    s.redirectDelaySec = Math.max(0, Math.round(sec))
    localStorage.setItem(KEYS.settings, JSON.stringify(s))
  },
  reset: () => {
    localStorage.setItem(KEYS.settings, JSON.stringify(DEFAULT_SETTINGS))
  },
}

