// ── Packet calculator ─────────────────────────────────────────────────────────
export function calcPackets(total: number, packetCount: number) {
  if (!total || !packetCount || packetCount < 1) return []
  const base  = Math.floor(total / packetCount)
  const extra = total % packetCount
  return Array.from({ length: packetCount }, (_, i) => ({
    index: i + 1,
    count: i === 0 ? base + extra : base,
    scoreRange: '',
  }))
}